package com.vividflash.dvdbounce;

import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.stream.ImageInputStream;
import lombok.extern.slf4j.Slf4j;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;

/**
 * An image with one or more frames. Static formats (PNG, JPG, BMP and so on)
 * load as a single frame; animated GIFs are composited into full frames with
 * per-frame delays so a renderer can pick the frame for any elapsed time.
 * Decoding uses the JRE's ImageIO and nothing else.
 */
@Slf4j
final class AnimatedImage
{
    /**
     * Caps on what a file may make this allocate. Decoded pixels are 4 bytes
     * each, so the numbers below are what actually bounds the memory a chosen
     * image can cost:
     * <ul>
     *   <li>{@link #MAX_DECODE_PIXELS} refuses a source larger than ImageIO
     *   should be asked to expand, before any buffer is allocated;</li>
     *   <li>{@link #MAX_GIF_CANVAS_PIXELS} bounds the compositing canvas, which
     *   is sized from the GIF header rather than from any decoded frame, and
     *   which a restoreToPrevious frame doubles;</li>
     *   <li>{@link #MAX_FRAMES} bounds how many frames are kept, each already
     *   downscaled by the caller's dimension cap;</li>
     *   <li>{@link #MAX_TOTAL_BYTES} stops a GIF accumulating frames past a
     *   total size, which matters most for a caller that asks for no
     *   downscale, where a frame is otherwise bounded only by the canvas
     *   cap.</li>
     * </ul>
     */
    private static final int MAX_FRAMES = 30;
    private static final long MAX_TOTAL_BYTES = 32L * 1024 * 1024;
    private static final long MAX_DECODE_PIXELS = 4096L * 4096L;
    private static final long MAX_GIF_CANVAS_PIXELS = 2048L * 2048L;

    /**
     * A declared frame delay below this is not believed, and
     * {@link #DEFAULT_DELAY_MS} is used instead. GIFs commonly declare 0, and
     * browsers render those at about 100 ms per frame rather than spinning
     * through them instantly.
     */
    private static final int MIN_DECLARED_DELAY_MS = 20;
    private static final int DEFAULT_DELAY_MS = 100;

    private final BufferedImage[] frames;
    /** Cumulative delay up to and including frame i, for elapsed-time lookup. */
    private final int[] frameEndTimesMs;
    private final int totalDurationMs;

    /**
     * The part of the image that is not fully transparent, in frame pixels,
     * covering every frame. Item sprites sit in a 36x32 box with padding around
     * them, so a renderer that bounces the whole box turns the picture around
     * before the visible part reaches the edge. Measured once here rather than
     * trimmed, so no pixel is lost.
     */
    private final Rectangle ink;

    private AnimatedImage(List<BufferedImage> frameList, List<Integer> delaysMs)
    {
        frames = frameList.toArray(new BufferedImage[0]);
        ink = inkBounds(frames);
        frameEndTimesMs = new int[frames.length];
        int total = 0;
        for (int i = 0; i < frames.length; i++)
        {
            total += delaysMs.get(i);
            frameEndTimesMs[i] = total;
        }
        totalDurationMs = total;
    }

    private AnimatedImage(BufferedImage single)
    {
        frames = new BufferedImage[]{single};
        frameEndTimesMs = new int[]{0};
        totalDurationMs = 0;
        ink = inkBounds(frames);
    }

    /**
     * The bounds of everything that is not fully transparent, across all
     * frames. An image with nothing in it reports its full size, so a caller
     * never has to handle an empty box.
     */
    private static Rectangle inkBounds(BufferedImage[] frames)
    {
        int minX = Integer.MAX_VALUE;
        int minY = Integer.MAX_VALUE;
        int maxX = -1;
        int maxY = -1;
        for (BufferedImage frame : frames)
        {
            int width = frame.getWidth();
            int height = frame.getHeight();
            int[] pixels = frame.getRGB(0, 0, width, height, null, 0, width);
            for (int y = 0; y < height; y++)
            {
                int row = y * width;
                for (int x = 0; x < width; x++)
                {
                    if ((pixels[row + x] & 0xFF000000) != 0)
                    {
                        minX = Math.min(minX, x);
                        maxX = Math.max(maxX, x);
                        minY = Math.min(minY, y);
                        maxY = Math.max(maxY, y);
                    }
                }
            }
        }
        if (maxX < 0)
        {
            return new Rectangle(0, 0, frames[0].getWidth(), frames[0].getHeight());
        }
        return new Rectangle(minX, minY, maxX - minX + 1, maxY - minY + 1);
    }

    int getInkX()
    {
        return ink.x;
    }

    int getInkY()
    {
        return ink.y;
    }

    int getInkWidth()
    {
        return ink.width;
    }

    int getInkHeight()
    {
        return ink.height;
    }

    /**
     * Wrap an already-decoded static image as a single-frame animation.
     */
    static AnimatedImage of(BufferedImage image)
    {
        return image == null ? null : new AnimatedImage(image);
    }

    /**
     * A source with more pixels than {@link #MAX_DECODE_PIXELS}. Separate from
     * the other failures so a caller can tell the user their file is too big,
     * rather than blaming its name or format.
     */
    static final class TooLargeException extends IOException
    {
        TooLargeException(int width, int height)
        {
            super("image is " + width + "x" + height + ", above the "
                + MAX_DECODE_PIXELS + " pixel cap");
        }
    }

    /**
     * Load an image file, decoding all frames if it is an animated GIF. Frames
     * are downscaled to {@code maxDimension} on their longest side; pass 0 to
     * leave the size untouched. Returns null when no ImageIO reader recognises
     * the file, and throws {@link TooLargeException} when the source holds more
     * than {@link #MAX_DECODE_PIXELS} pixels. A GIF whose declared canvas is
     * too large loads as its first frame only.
     */
    static AnimatedImage load(File file, int maxDimension) throws IOException
    {
        try (ImageInputStream input = ImageIO.createImageInputStream(file))
        {
            if (input == null)
            {
                return null;
            }
            Iterator<ImageReader> readers = ImageIO.getImageReaders(input);
            if (!readers.hasNext())
            {
                return null;
            }
            ImageReader reader = readers.next();
            try
            {
                reader.setInput(input);
                int width = reader.getWidth(0);
                int height = reader.getHeight(0);
                if ((long) width * height > MAX_DECODE_PIXELS)
                {
                    throw new TooLargeException(width, height);
                }

                int frameCount = "gif".equalsIgnoreCase(reader.getFormatName())
                    ? reader.getNumImages(true) : 1;
                if (frameCount > 1)
                {
                    AnimatedImage animated = decodeGif(reader, frameCount, maxDimension);
                    if (animated != null)
                    {
                        return animated;
                    }
                }
                return of(downscale(reader.read(0), maxDimension));
            }
            finally
            {
                reader.dispose();
            }
        }
    }

    /**
     * The frame to show {@code elapsedMs} after the animation started; the
     * animation loops. Static images always return their only frame.
     */
    BufferedImage frameAt(long elapsedMs)
    {
        if (frames.length == 1 || totalDurationMs <= 0)
        {
            return frames[0];
        }
        long t = elapsedMs % totalDurationMs;
        if (t < 0)
        {
            t += totalDurationMs;
        }
        for (int i = 0; i < frames.length; i++)
        {
            if (t < frameEndTimesMs[i])
            {
                return frames[i];
            }
        }
        return frames[frames.length - 1];
    }

    int getWidth()
    {
        return frames[0].getWidth();
    }

    int getHeight()
    {
        return frames[0].getHeight();
    }

    /**
     * Composite a multi-frame GIF into standalone full frames. GIF frames are
     * often partial diffs positioned inside a logical screen, so each frame is
     * drawn onto a persistent canvas and the canvas snapshotted, honouring the
     * frame's disposal method before the next one. Returns null when the
     * declared canvas is above {@link #MAX_GIF_CANVAS_PIXELS}, leaving the
     * caller to fall back to a single frame.
     */
    private static AnimatedImage decodeGif(ImageReader reader, int frameCount, int maxDimension)
        throws IOException
    {
        int canvasWidth = 0;
        int canvasHeight = 0;
        IIOMetadata streamMetadata = reader.getStreamMetadata();
        if (streamMetadata != null)
        {
            Node screen = findNode(streamMetadata.getAsTree("javax_imageio_gif_stream_1.0"),
                "LogicalScreenDescriptor");
            canvasWidth = intAttribute(screen, "logicalScreenWidth", 0);
            canvasHeight = intAttribute(screen, "logicalScreenHeight", 0);
        }
        if (canvasWidth <= 0 || canvasHeight <= 0)
        {
            canvasWidth = reader.getWidth(0);
            canvasHeight = reader.getHeight(0);
        }
        if ((long) canvasWidth * canvasHeight > MAX_GIF_CANVAS_PIXELS)
        {
            log.debug("GIF declares a {}x{} canvas, above the {} pixel cap; using one frame",
                canvasWidth, canvasHeight, MAX_GIF_CANVAS_PIXELS);
            return null;
        }

        BufferedImage canvas = new BufferedImage(canvasWidth, canvasHeight,
            BufferedImage.TYPE_INT_ARGB);
        List<BufferedImage> frames = new ArrayList<>();
        List<Integer> delays = new ArrayList<>();
        long totalBytes = 0;

        for (int i = 0; i < frameCount; i++)
        {
            BufferedImage frame = reader.read(i);
            IIOMetadata frameMetadata = reader.getImageMetadata(i);
            Node tree = frameMetadata == null
                ? null : frameMetadata.getAsTree("javax_imageio_gif_image_1.0");
            Node descriptor = findNode(tree, "ImageDescriptor");
            Node control = findNode(tree, "GraphicControlExtension");
            int x = intAttribute(descriptor, "imageLeftPosition", 0);
            int y = intAttribute(descriptor, "imageTopPosition", 0);
            int delayMs = intAttribute(control, "delayTime", 0) * 10;
            if (delayMs < MIN_DECLARED_DELAY_MS)
            {
                delayMs = DEFAULT_DELAY_MS;
            }
            String disposal = stringAttribute(control, "disposalMethod", "none");

            BufferedImage restore = "restoreToPrevious".equals(disposal) ? copy(canvas) : null;

            Graphics2D g = canvas.createGraphics();
            g.drawImage(frame, x, y, null);
            g.dispose();

            BufferedImage snapshot = snapshot(canvas, maxDimension);
            totalBytes += (long) snapshot.getWidth() * snapshot.getHeight() * 4;
            frames.add(snapshot);
            delays.add(delayMs);

            if (frames.size() >= MAX_FRAMES || totalBytes > MAX_TOTAL_BYTES)
            {
                if (i + 1 < frameCount)
                {
                    log.warn("Animated GIF truncated to {} of {} frames to bound memory use",
                        frames.size(), frameCount);
                }
                break;
            }

            if ("restoreToBackgroundColor".equals(disposal))
            {
                Graphics2D clear = canvas.createGraphics();
                clear.setComposite(AlphaComposite.Clear);
                clear.fillRect(x, y, frame.getWidth(), frame.getHeight());
                clear.dispose();
            }
            else if (restore != null)
            {
                canvas = restore;
            }
        }

        return new AnimatedImage(frames, delays);
    }

    /**
     * An independent copy of the canvas, downscaled to {@code maxDimension}
     * on its longest side (0 = keep size). Always allocates so later canvas
     * mutations cannot bleed into stored frames.
     */
    private static BufferedImage snapshot(BufferedImage canvas, int maxDimension)
    {
        int longest = Math.max(canvas.getWidth(), canvas.getHeight());
        if (maxDimension <= 0 || longest <= maxDimension)
        {
            return copy(canvas);
        }
        double scale = (double) maxDimension / longest;
        int w = Math.max(1, (int) Math.round(canvas.getWidth() * scale));
        int h = Math.max(1, (int) Math.round(canvas.getHeight() * scale));
        BufferedImage scaled = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = scaled.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(canvas, 0, 0, w, h, null);
        g.dispose();
        return scaled;
    }

    private static BufferedImage downscale(BufferedImage image, int maxDimension)
    {
        if (image == null)
        {
            return null;
        }
        int longest = Math.max(image.getWidth(), image.getHeight());
        if (maxDimension <= 0 || longest <= maxDimension)
        {
            return image;
        }
        return snapshot(image, maxDimension);
    }

    private static BufferedImage copy(BufferedImage source)
    {
        BufferedImage out = new BufferedImage(source.getWidth(), source.getHeight(),
            BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.drawImage(source, 0, 0, null);
        g.dispose();
        return out;
    }

    private static Node findNode(Node root, String name)
    {
        for (Node child = root == null ? null : root.getFirstChild();
            child != null; child = child.getNextSibling())
        {
            if (name.equals(child.getNodeName()))
            {
                return child;
            }
        }
        return null;
    }

    private static int intAttribute(Node node, String attribute, int fallback)
    {
        String value = stringAttribute(node, attribute, null);
        if (value == null)
        {
            return fallback;
        }
        try
        {
            return Integer.parseInt(value);
        }
        catch (NumberFormatException e)
        {
            return fallback;
        }
    }

    private static String stringAttribute(Node node, String attribute, String fallback)
    {
        if (node == null)
        {
            return fallback;
        }
        NamedNodeMap attributes = node.getAttributes();
        Node value = attributes == null ? null : attributes.getNamedItem(attribute);
        return value == null ? fallback : value.getNodeValue();
    }
}

